#nullable enable // autogenerated

using System.Collections.Generic;
using MVZ2.GameContent.Buffs.Bosses;
using MVZ2.GameContent.Damages;
using MVZ2.Vanilla;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Bosses;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Entities;
using MVZ2Logic.Level;
using PVZEngine.Buffs;
using PVZEngine.Collisions;
using PVZEngine.Damages;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Modifiers;
using PVZEngine.Tools;
using PVZEngine.Tools.Random;
using UnityEngine;

namespace MVZ2.GameContent.Bosses
{
    [AutoEntityBehaviourDefinition(VanillaBossNames.kraken)]
    public partial class Kraken : BossBehaviour
    {
        public Kraken(string nsp, string name) : base(nsp, name)
        {
            AddModifier(new FloatModifier(LogicEntityProps.SHADOW_ALPHA, NumberOperator.Multiply, PROP_SHADOW_ALPHA));
            AddModifier(new BooleanModifier(EngineEntityProps.INVINCIBLE, PROP_INVINCIBLE));
            AddModifier(new BooleanModifier(VanillaEntityProps.INVISIBLE, PROP_INVINCIBLE));
        }

        #region 回调
        public override void Init(Entity boss)
        {
            base.Init(boss);
            stateMachine.Init(boss);
            stateMachine.StartState(boss, STATE_HIDDEN);
            ResummonTentacles(boss, 2, true);
        }
        protected override void UpdateAI(Entity entity)
        {
            base.UpdateAI(entity);
            stateMachine.UpdateAI(entity);
        }
        protected override void UpdateLogic(Entity entity)
        {
            base.UpdateLogic(entity);
            stateMachine.UpdateLogic(entity);
        }
        public override void PostCollision(EntityCollision collision, int state)
        {
            base.PostCollision(collision, state);
            if (state == EntityCollisionHelper.STATE_EXIT)
                return;
            var other = collision.Other;
            var self = collision.Entity;
            if (self.IsDead)
                return;
            if (!other.Exists() || !other.IsHostile(self))
                return;
            var otherCollider = collision.OtherCollider;
            if (!other.IsInvincible() && other.Type == EntityTypes.PLANT)
            {
                self.BossCrush(otherCollider);
            }
        }
        #endregion 事件

        public static void PlaySplash(Entity entity)
        {
            entity.PlaySound(VanillaSoundID.splashBig, pitch: 0.75f);
            entity.PlaySplashEffectAt(entity.Position, SPLASH_EFFECT_SCALE);
        }
        public static void SwitchToPhase2(Entity entity)
        {
            entity.SetPhase(PHASE_2);
            RecallAllAliveTentacles(entity);
            stateMachine.StartState(entity, STATE_APPEAR);
        }
        public static void SwitchToPhase3(Entity entity)
        {
            entity.SetPhase(PHASE_3);
            RecallAllAliveTentacles(entity);
            stateMachine.StartState(entity, STATE_SWITCH_PHASE_2);
        }

        public static void SetInactive(Entity entity, bool inactive)
        {
            if (inactive)
            {
                if (!entity.HasBuff<KrakenInactiveBuff>())
                {
                    entity.AddBuff<KrakenInactiveBuff>();
                }
            }
            else
            {
                entity.RemoveBuffs<KrakenInactiveBuff>();
            }
        }
        public static void AdjustZ(Entity entity)
        {
            var position = entity.Position;
            position.z = entity.Level.GetLaneCenterZFloat((entity.Level.GetMaxLaneCount() - 1) * 0.5f);
            entity.Position = position;
        }
        #region 触手
        public static void RecallAllAliveTentacles(Entity entity)
        {
            var tentacles = GetTentacles(entity);
            if (tentacles == null)
                return;
            foreach (var tentacleID in tentacles)
            {
                var tentacle = tentacleID.GetEntity(entity.Level);
                if (!tentacle.ExistsAndAlive())
                    continue;
                RecallTentacle(tentacle);
            }
            ClearDeadTentacles(entity);
        }
        public static void RecallTentacle(Entity tentacle)
        {
            KrakenTentacle.Recall(tentacle);
        }
        public static void ResummonTentacles(Entity entity, int count, bool autoAct)
        {
            var tentacles = GetTentacles(entity);
            if (tentacles == null)
            {
                tentacles = new List<EntityID>();
                SetTentacles(entity, tentacles);
            }
            var spawnParams = entity.GetSpawnParams();
            spawnParams.EntityParent = entity;
            spawnParams.SetProperty(KrakenTentacle.PROP_AUTO_ACT, autoAct);

            using var nextActionsItem = ListPool<int>.Rent();
            var nextActions = nextActionsItem.Value;
            KrakenTentacle.actionPool.RandomTake(count, entity.RNG, nextActions);
            for (int i = 0; i < count; i++)
            {
                spawnParams.SetProperty(KrakenTentacle.PROP_NEXT_ACTION, nextActions[i % nextActions.Count]);
                var tentacle = entity.Spawn(VanillaBossID.krakenTentacle, entity.Position, spawnParams);
                tentacles.Add(new EntityID(tentacle));
            }
            ClearDeadTentacles(entity);
        }
        public static void CommandTentaclesToAttack(Entity entity)
        {
            var tentacles = GetTentacles(entity);
            if (tentacles != null)
            {
                foreach (var tentacleID in tentacles)
                {
                    var tentacle = tentacleID.GetEntity(entity.Level);
                    if (!tentacle.ExistsAndAlive())
                        continue;
                    KrakenTentacle.CommandAttack(tentacle);
                }
                ClearDeadTentacles(entity);
            }
        }
        public static bool AllTentaclesAreDead(Entity entity)
        {
            var tentacles = GetTentacles(entity);
            if (tentacles != null)
            {
                foreach (var tentacleID in tentacles)
                {
                    var tentacle = tentacleID.GetEntity(entity.Level);
                    if (tentacle.ExistsAndAlive())
                        return false;
                }
            }
            return true;
        }
        public static void ClearDeadTentacles(Entity entity)
        {
            var tentacles = GetTentacles(entity);
            if (tentacles != null)
            {
                tentacles.RemoveAll(t => !t.Exists(entity.Level));
            }
        }
        public static void KillAllTentacles(Entity entity)
        {
            var tentacles = GetTentacles(entity);
            if (tentacles != null)
            {
                var effects = new DamageEffectList(VanillaDamageEffects.INSTA_KILL);
                foreach (var tentacleID in tentacles)
                {
                    var tentacle = tentacleID.GetEntity(entity.Level);
                    if (tentacle == null || tentacle.IsDead)
                        continue;
                    tentacle.Die(effects, entity);
                }
            }
        }
        #endregion


        #region 字段
        public static bool GetInvincible(Entity entity) => entity.GetBehaviourField<bool>(PROP_INVINCIBLE);
        public static void SetInvincible(Entity entity, bool value) => entity.SetBehaviourField(PROP_INVINCIBLE, value);
        public static List<EntityID>? GetTentacles(Entity entity) => entity.GetBehaviourField<List<EntityID>>(PROP_TENTACLES);
        public static void SetTentacles(Entity entity, List<EntityID>? value) => entity.SetBehaviourField(PROP_TENTACLES, value);
        public static float GetShadowAlpha(Entity entity) => entity.GetBehaviourField<float>(PROP_SHADOW_ALPHA);
        public static void SetShadowAlpha(Entity entity, float value) => entity.SetBehaviourField(PROP_SHADOW_ALPHA, value);
        #endregion

        #region 常量
        public static readonly VanillaEntityPropertyMeta<bool> PROP_INVINCIBLE = new VanillaEntityPropertyMeta<bool>("invincible");
        public static readonly VanillaEntityPropertyMeta<List<EntityID>> PROP_TENTACLES = new VanillaEntityPropertyMeta<List<EntityID>>("tentacles");
        public static readonly VanillaEntityPropertyMeta<float> PROP_SHADOW_ALPHA = new VanillaEntityPropertyMeta<float>("shadow_alpha", 0);

        public static readonly Vector3 SPLASH_EFFECT_SCALE = Vector3.one * 8f;

        public const int PHASE_1 = 0;
        public const int PHASE_2 = 1;
        public const int PHASE_3 = 2;

        public const float ROAR_SECONDS = 4f;

        // Phase 1
        public const int STATE_HIDDEN = VanillaBossStates.KRAKEN_HIDDEN;

        // Phase 2
        public const int STATE_APPEAR = VanillaBossStates.APPEAR;
        public const int STATE_IDLE = VanillaBossStates.IDLE;

        public const int STATE_BARRAGE_EYE = VanillaBossStates.KRAKEN_BARRAGE_EYE;
        public const int STATE_FLAME_EYE = VanillaBossStates.KRAKEN_FLAME_EYE;
        public const int STATE_ROAR = VanillaBossStates.KRAKEN_ROAR;
        public const int STATE_LASER_EYE = VanillaBossStates.KRAKEN_LASER_EYE;
        public const int STATE_ABSORB = VanillaBossStates.KRAKEN_ABSORB;
        public const int STATE_DRAINAGE = VanillaBossStates.KRAKEN_DRAINAGE;

        // Phase 3
        public const int STATE_SWITCH_PHASE_2 = VanillaBossStates.KRAKEN_SWITCH_PHASE_2;
        public const int STATE_COMMAND_ROAR = VanillaBossStates.KRAKEN_COMMAND_ROAR;
        public const int STATE_TIME_BOMB = VanillaBossStates.KRAKEN_TIME_BOMB;

        // Extra
        public const int STATE_STUNNED = VanillaBossStates.STUNNED;
        public const int STATE_DEATH = VanillaBossStates.DEATH;

        public const int ANIMATION_STATE_IDLE = 0;
        public const int ANIMATION_STATE_APPEAR = 1;
        public const int ANIMATION_STATE_STUNNED = 2;
        public const int ANIMATION_STATE_DEATH = 3;
        public const int ANIMATION_STATE_ROAR = 10000;
        public const int ANIMATION_STATE_DIVE = 10001;
        public const int ANIMATION_STATE_HIDDEN = 10002;
        public const int ANIMATION_STATE_LASER_EYE = 10003;
        public const int ANIMATION_STATE_ABSORB = 10004;
        #endregion 常量
    }
}
